ns:minmax(0,1.18fr) minmax(330px,.82fr);gap:30px;align-items:start}.board-topline{display:flex;align-items:center;justify-content:space-between;margin:0 2px 12px}.board-label{font:10px var(--mono);letter-spacing:.12em;color:#e4dec9}.sun-icon{font-size:17px;color:#d6b46d;vertical-align:-2px;margin-right:7px}.board-sub{color:#829184}.turn-pill{padding:7px 10px;border:1px solid rgba(227,235,208,.13);border-radius:20px;font:9px var(--mono);letter-spacing:.09em;color:#c7cdbc}.turn-pill .turn-dot{width:6px;height:6px}.board-frame{position:relative;padding:15px 15px 35px;background:linear-gradient(145deg,#604c32,#392e22 40%,#4b3826);border:1px solid #8b714c;border-radius:7px;box-shadow:0 18px 50px #03090777,inset 0 1px #c5a77b55,inset 0 -7px 18px #241a12}.board-frame:before{content:"";position:absolute;inset:5px;border:1px solid #d5bc8b2b;border-radius:4px;pointer-events:none}.board-screws{position:absolute;inset:8px 8px auto;display:flex;justify-content:space-between;z-index:2;pointer-events:none}.board-screws i{width:5px;height:5px;border-radius:50%;background:#aa8a5b;box-shadow:inset 0 1px 2px #302316}.board-screws i:nth-child(3),.board-screws i:nth-child(4){position:absolute;top:calc(min(68vw, 680px) + 35px)}.board-screws i:nth-child(4){right:0}.board-frame svg{display:block;width:100%;aspect-ratio:1;border-radius:2px;box-shadow:0 3px 12px #080f0a70}.board-caption{position:absolute;bottom:12px;left:22px;right:22px;display:flex;justify-content:space-between;color:#c7ae83;font:8px var(--mono);letter-spacing:.12em}.board-legend{display:flex;align-items:center;gap:20px;padding:14px 5px;color:#a1ad9f;font:9px var(--mono);letter-spacing:.07em}.board-legend span{display:flex;align-items:center;gap:7px}.legend-grass{width:11px;height:11px;border-radius:3px;background:#769e5e}.legend-safe{font:14px var(--sans);color:#ddc27c}.legend-home{font:16px var(--sans);color:#d4be8d}.control-panel{background:linear-gradient(150deg,#1b2c23,#14231d);border:1px solid rgba(226,232,210,.13);border-radius:8px;padding:24px 24px 19px;box-shadow:0 18px 40px #0309073d}.panel-heading{display:flex;align-items:start;justify-content:space-between}.panel-heading h2{font:600 25px var(--serif);margin:0;letter-spacing:-.02em}.panel-heading .eyebrow{margin-bottom:7px}.round-count{padding:6px 8px;border:1px solid var(--line);border-radius:3px;color:#9da99a;font:9px var(--mono);letter-spacing:.08em}.dice-stage{height:150px;display:flex;align-items:center;justify-content:center;position:relative;flex-direction:column}.dice-shadow{position:absolute;top:108px;width:62px;height:14px;background:#050d08;filter:blur(10px);border-radius:50%;opacity:.8}.die{position:relative;width:65px;height:65px;border:1px solid #f6e8cb;border-radius:13px;background:linear-gradient(145deg,#f6efdb,#d4c6a9);box-shadow:0 8px 0 #9e8e70,0 13px 20px #050c08aa,inset 1px 2px 5px #fff;cursor:pointer;transform:rotate(-7deg);transition:transform .2s}.die:hover{transform:rotate(0) translateY(-2px)}.die:disabled{cursor:default}.pip-grid{display:grid;grid-template:repeat(3,8px)/repeat(3,8px);gap:8px;justify-content:center;align-content:center;height:100%;transform:rotate(7deg)}.pip-grid i{width:8px;height:8px;border-radius:50%;background:#34473c;opacity:0}.pip-grid[data-value="1"] i:nth-child(5),.pip-grid[data-value="2"] i:nth-child(1),.pip-grid[data-value="2"] i:nth-child(9),.pip-grid[data-value="3"] i:nth-child(1),.pip-grid[data-value="3"] i:nth-child(5),.pip-grid[data-value="3"] i:nth-child(9),.pip-grid[data-value="4"] i:nth-child(1),.pip-grid[data-value="4"] i:nth-child(3),.pip-grid[data-value="4"] i:nth-child(7),.pip-grid[data-value="4"] i:nth-child(9),.pip-grid[data-value="5"] i:nth-child(1),.pip-grid[data-value="5"] i:nth-child(3),.pip-grid[data-value="5"] i:nth-child(5),.pip-grid[data-value="5"] i:nth-child(7),.pip-grid[data-value="5"] i:nth-child(9),.pip-grid[data-value="6"] i:nth-child(1),.pip-grid[data-value="6"] i:nth-child(3),.pip-grid[data-value="6"] i:nth-child(4),.pip-grid[data-value="6"] i:nth-child(6),.pip-grid[data-value="6"] i:nth-child(7),.pip-grid[data-value="6"] i:nth-child(9){opacity:1}.dice-hint{position:absolute;bottom:3px;color:#9ba99a;font:9px var(--mono);letter-spacing:.12em}.rolling .die{animation:roll .58s cubic-bezier(.4,0,.2,1)}@keyframes roll{0%{transform:rotate(-7deg) scale(1)}45%{transform:rotate(190deg) scale(1.13)}100%{transform:rotate(353deg) scale(1)}}.roll-btn{width:100%;display:flex;align-items:center;justify-content:space-between;border:0;border-radius:4px;padding:14px 16px;background:#d5ae6a;color:#1b251c;font:700 10px var(--mono);letter-spacing:.13em;cursor:pointer;box-shadow:0 3px 0 #957744;transition:background .16s,transform .16s}.roll-btn:hover{background:#e5c181;transform:translateY(-1px)}.roll-btn:disabled{opacity:.46;cursor:default;transform:none}.btn-arrow{font-size:16px;line-height:10px}.move-message{min-height:35px;padding:11px 1px 10px;color:#b5c0b1;font-size:11px;line-height:1.4}.roster-heading{display:flex;justify-content:space-between;color:#859385;font:9px var(--mono);letter-spacing:.13em;padding:12px 0 7px;border-top:1px solid var(--line)}.roster{display:flex;flex-direction:column}.crew-row{min-height:45px;display:flex;align-items:center;gap:9px;border-bottom:1px solid rgba(227,235,208,.07);font-size:12px}.crew-swatch{width:9px;height:9px;border-radius:3px;background:var(--crew);box-shadow:0 0 9px color-mix(in srgb,var(--crew) 35%,transparent)}.crew-name{flex:1;color:#e1e4d7;font-weight:600}.crew-role{color:#879487;font-size:10px;margin-left:4px;font-weight:400}.crew-count{font:10px var(--mono);color:#b4bfaf}.crew-count b{color:#eee4cd;font-weight:500}.crew-active{background:linear-gradient(90deg,color-mix(in srgb,var(--crew) 11%,transparent),transparent);margin:0 -8px;padding:0 8px;border-radius:4px}.crew-turn{width:14px;color:var(--crew);font-size:13px}.event-card{margin-top:14px;padding:11px 12px;background:#ffffff06;border:1px solid rgba(226,232,210,.09);border-radius:4px;display:flex;gap:10px;align-items:center}.event-icon{color:#d9b672;font-size:16px}.event-card strong{font:600 10px var(--mono);letter-spacing:.06em;color:#d4bd8d}.event-card p{font-size:10px;color:#9eaa9b;margin:4px 0 0;line-height:1.4}.panel-footer{display:flex;justify-content:space-between;padding-top:16px}.text-btn{background:none;border:0;padding:4px 0;color:#a3afa0;font:9px var(--mono);letter-spacing:.07em;cursor:pointer}.text-btn:hover{color:#e5c181}.page-footer{padding:30px 2px 20px;display:flex;justify-content:space-between;color:#7e8d7f;font:9px var(--mono);letter-spacing:.1em}.page-footer b{color:#d0ad68;margin-left:6px}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#09110dcc;display:grid;place-items:center;padding:20px;backdrop-filter:blur(5px)}.modal-backdrop[hidden]{display:none}.modal{position:relative;max-width:460px;width:100%;padding:35px 36px;background:#1a2c23;border:1px solid #9a815544;border-radius:7px;box-shadow:0 24px 80px #0009}.modal h2{font:700 34px var(--serif);margin:0 0 15px}.modal p,.modal li{font-size:13px;line-height:1.7;color:#b4c0b2}.modal ul{padding-left:19px}.modal li{padding:3px 0}.modal .note-line{color:#d0b77f;font-size:11px}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;color:#b7c1b4;font-size:24px;cursor:pointer}.modal-ok{margin-top:9px}.toast{position:fixed;bottom:26px;left:50%;transform:translate(-50%,20px);z-index:12;padding:11px 17px;border-radius:4px;background:#e4c27e;color:#17231b;font:600 11px var(--mono);box-shadow:0 6px 22px #0008;opacity:0;pointer-events:none;transition:all .22s}.toast.show{opacity:1;transform:translate(-50%,0)}
/* SVG board pieces */
.cell{stroke:#31492e;stroke-width:1}.yard-cell{fill:url(#grass)}.path-cell{fill:#e2d9be;stroke:#879675}.safe-cell{fill:#f1e7c9}.lane-green{fill:#b5cf9e}.lane-gold{fill:#e7ca8e}.lane-red{fill:#dda297}.lane-blue{fill:#a8bee0}.house-base{stroke:#ded1ae;stroke-width:2}.pawn{cursor:pointer;transition:filter .15s}.pawn .pawn-shadow{fill:#0c160e;opacity:.48}.pawn .body{stroke:#f5e9d1;stroke-width:1.2}.pawn .head{stroke:#f8ecd5;stroke-width:1.2}.pawn .knife{stroke:#f2e8d1;stroke-width:2;stroke-linecap:round}.pawn .knife-hilt{stroke:#35251d;stroke-width:2.5;stroke-linecap:round}.pawn.movable{filter:drop-shadow(0 0 5px #f4d57c);animation:bob 1s ease-in-out infinite alternate}.pawn.movable .body{stroke:#fff4b1;stroke-width:2}.pawn.selected{filter:drop-shadow(0 0 7px #ffe18d)}.pawn .backstab{display:none}.pawn.caught .backstab{display:block}.pawn.caught .backstab circle{fill:#f1d58a;stroke:#fff1c8;stroke-width:1.3}.pawn.caught .backstab path{stroke:#9b433a;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;fill:none}.pawn.hit{animation:pop .5s ease}@keyframes bob{to{transform:translateY(-3px)}}@keyframes pop{50%{transform:scale(1.18) rotate(-8deg)}}.house-label{font:700 9px var(--mono);letter-spacing:.12em;fill:#f0e5ca}.house-small{font:8px var(--mono);letter-spacing:.1em;fill:#d7ccb1}.yard-decoration{opacity:.6}.goal-star{fill:#edd69e}.track-number{font:5px var(--mono);fill:#6c7d66;opacity:.57}
